{"content":"from flask import Flask, request, jsonify
from transformers import pipeline

MODEL_PATH = "/app/model_cache/sentiment_model"

app = Flask(__name__)

# Load pipeline once at startup from local cache
classifier = pipeline(
    "sentiment-analysis",
    model=MODEL_PATH,
    tokenizer=MODEL_PATH,
    top_k=None,
)


@app.route("/sentiment", methods=["POST"])
def sentiment():
    try:
        data = request.get_json(force=True, silent=True)
    except Exception:
        data = None
    if not isinstance(data, dict) or "text" not in data:
        return jsonify({"error": 'Missing required field: \"text\"'}), 400
    text = data.get("text")
    if not isinstance(text, str) or not text.strip():
        return jsonify({"error": 'Field \"text\" must be a non-empty string'}), 400
    try:
        results = classifier(text)
        # pipeline with top_k=None returns list of list of dicts
        # e.g. [[{'label': 'POSITIVE', 'score': 0.99}, {'label': 'NEGATIVE', ...}]]
        if isinstance(results, list) and len(results) > 0 and isinstance(results[0], list):
            scores = results[0]
        elif isinstance(results, list) and len(results) > 0 and isinstance(results[0], dict):
            scores = results
        else:
            return jsonify({"error": "Unexpected model output"}), 500
        conf = {"positive": 0.0, "negative": 0.0}
        for item in scores:
            label = str(item.get("label", "")).upper()
            score = float(item.get("score", 0.0))
            if label == "POSITIVE":
                conf["positive"] = score
            elif label == "NEGATIVE":
                conf["negative"] = score
        sentiment_label = "positive" if conf["positive"] >= conf["negative"] else "negative"
        return jsonify({"sentiment": sentiment_label, "confidence": conf})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/health", methods=["GET"])
def health():
    return jsonify({"status": "ok"})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
